{
  "items": [
    {
      "name": "matPolyEquiv_diagonal_X",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] {n : Type w} [inst_1 : DecidableEq n] [inst_2 : Fintype n],\n  matPolyEquiv (Matrix.diagonal fun x => Polynomial.X) = Polynomial.X"
    },
    {
      "name": "MvPolynomial.bind₁",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} →\n    {R : Type u_3} → [inst : CommSemiring R] → (σ → MvPolynomial τ R) → MvPolynomial σ R →ₐ[R] MvPolynomial τ R"
    },
    {
      "name": "MvPowerSeries.subst_self",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R], MvPowerSeries.subst MvPowerSeries.X = id"
    },
    {
      "name": "MvPolynomial.bind₁_X_left",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R],\n  MvPolynomial.bind₁ MvPolynomial.X = AlgHom.id R (MvPolynomial σ R)"
    },
    {
      "name": "MvPowerSeries.subst_X",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a → ∀ (s : σ), MvPowerSeries.subst a (MvPowerSeries.X s) = a s"
    },
    {
      "name": "Polynomial.toMvPolynomial_X",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_3} [inst : CommSemiring R] (i : σ),\n  (Polynomial.toMvPolynomial i) Polynomial.X = MvPolynomial.X i"
    },
    {
      "name": "Polynomial.toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "{R : Type u_1} → {σ : Type u_3} → [inst : CommSemiring R] → σ → Polynomial R →ₐ[R] MvPolynomial σ R"
    },
    {
      "name": "MvPowerSeries.subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {R : Type u_3} →\n    [inst : CommRing R] →\n      {τ : Type u_4} →\n        {S : Type u_5} →\n          [inst_1 : CommRing S] → [Algebra R S] → (σ → MvPowerSeries τ S) → MvPowerSeries σ R → MvPowerSeries τ S"
    }
  ]
}
